-- Din Felsefesi I, 3. hafta: yeniden yazılan Zapoot (20) ve Quiz (15) soruları, ayrı paketler olarak eklenir (eski paketlere dokunulmaz).
-- Kaynak: docs/soru-onerileri/yeni/h03.txt. Aynı soru metni varsa atlanır. 16 Kasım 2026 kullanıcı onayıyla.
do $$
declare v_icerik uuid;
begin
  select id into v_icerik from public.subjects where ad = 'Din Felsefesi I' limit 1;
  if v_icerik is null then raise exception 'Din Felsefesi I içeriği bulunamadı'; end if;
  insert into public.questions (subject_id, soru, dogru, yanlislar, sure_sn, ek)
  select v_icerik, x->>'s', x->>'d', array(select jsonb_array_elements_text(x->'y')), (x->>'t')::int,
         jsonb_build_object('paket', x->>'p', 'konu', x->>'k', 'zorluk', x->>'z', 'bloom', x->>'b')
  from jsonb_array_elements($j$[{"s":"Din ile felsefenin önermeleri çoğu zaman benzerlik gösterir. Bu önermeleri birbirinden ayıran temel ölçüt hangisidir?","d":"Dayandıkları kaynak: dinde büyük ölçüde vahiy, felsefede büyük ölçüde insan aklı","y":["Kullandıkları dilin ağırlığı: dinde sade, felsefede teknik bir terminoloji","Ele aldıkları varlık alanı: dinde âhiret, felsefede dünya hayatı","İleri sürüldükleri dönem: dinde eski çağlar, felsefede modern çağlar"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"orta","b":"Anlama"},{"s":"Hem dinin hem felsefenin işlediği ortak bir metafizik kavram aşağıdakilerden hangisidir?","d":"Ruhun ebedîliği","y":["Atomun yapısı","Mülkiyet hakkı","Mantıksal çelişmezlik"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"kolay","b":"Hatırlama"},{"s":"Bir filozof aklî delillerle “Allah vardır ve birdir” hükmüne ulaşıyor. Bu hükmün başkaları için durumu hakkında hangisi söylenebilir?","d":"Başkaları için aynı geçerliliği taşımayabilir; çünkü filozofun yargısı ferdî ve tartışmaya açıktır","y":["Bütün insanlar için aynı kesinlikte geçerlidir; çünkü akıl yoluyla ulaşılan hüküm herkesi bağlar","Filozof için de kesin değildir; çünkü aklî delille ulaşılan hükümler genel kabul görmez ve geçersiz sayılır","Ancak başka filozoflar için geçerlidir; çünkü sıradan insanlar bu tür hükümleri kavrayacak donanıma sahip değildir"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"zor","b":"Analiz"},{"s":"Aynı “Allah vardır ve birdir” hükmü dinin yargısı olarak sunulduğunda inananından ne beklenir?","d":"Hükmü kesin olarak kabul etmesi","y":["Hükmü her defasında yeniden ispatlaması","Hükme karşı ilgisiz kalması","Hükmü duygusal bulması"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"orta","b":"Anlama"},{"s":"Tevhit esasına dayalı dinlerde iman nasıl bir kabuldür?","d":"Dayatma değil, iradeli bir kabullenme ve tasdik","y":["Sorgulamayı engelleyen zorunlu bir itaat","Duygusal bir coşkudan ibaret bir hâl","Toplumsal baskıyla oluşan bir alışkanlık"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"orta","b":"Anlama"},{"s":"Allah’ın varlığını ispat çabası filozof için neden ayrı bir önem taşır?","d":"Sistemin dayandığı ilkeyi ispatlamak, sistemi tutarlı kılmanın koşuludur","y":["Dinî otoriteler böyle bir ispatı zorunlu kılmış ve filozoflardan bunu açıkça istemiştir","İspat yapılmazsa filozofun adı felsefe tarihinden silinir ve görüşleri değerlendirilmez","Bu ispat ancak matematik bilgisine sahip kişilerin yapabileceği özel bir görevdir"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"orta","b":"Analiz"},{"s":"Platon için söylenen “Yunanca konuşan Musa” sözü hangi iddiayı yansıtır?","d":"Filozofların fikir ve kavramlarını vahiy kaynağından aldığı iddiasını","y":["Platon’un Yunanca yazan ilk peygamber olduğunu ve kutsal bir metin bıraktığını","Musa’nın Yunan felsefesinin kurucusu olduğunu ve Platon’a bunu öğrettiğini","Platon’un farklı dinleri birbirine karıştırıp yeni bir din kurduğunu"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Kavramlar","z":"orta","b":"Anlama"},{"s":"İbn Sînâ’ya göre felsefenin gayesi hangi ifadeyle özetlenir?","d":"Nesnelerin hakikatlerine insanın vakıf olabileceği kadar vakıf olmak","y":["Bütün bilimleri tek bir bilimin içinde birleştirmek","Dinî hükümleri tartışma dışında bırakmak","Doğa olaylarını deneyle ölçmek ve sınıflandırmak"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"orta","b":"Hatırlama"},{"s":"Kitapta Platon’un felsefe tanımı hangi ifadeyle aktarılır?","d":"Kişinin gücü nisbetinde Tanrı’ya benzemesi","y":["Duyularla algılanan nesnelerin sistemli listesi","Devlet yönetiminin teknik bilgisi","Mantık kurallarının ezberlenmesi ve uygulanması"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"orta","b":"Hatırlama"},{"s":"Yeni pozitivist mantık okulu felsefenin görevini kavram analizine indirger. Kitaptaki eleştiriye göre bu yaklaşımın sorunu nedir?","d":"Kavram üretmek felsefenin görevlerinden yalnızca biridir; gayeyi buna indirmek felsefenin genel tutumuna aykırıdır","y":["Kavram analizi felsefeyle ilgisi bulunmayan, dilbilime ait bir uğraştır; bu yüzden felsefenin konusu olamaz ve dışarıda tutulmalıdır","Kavram analizi çok zor bir iştir; bu yüzden filozofların altından kalkamayacağı ve bilim insanlarına bırakılması gereken bir görevdir","Kavram analizi yapılınca felsefe dinin yerini alır; böylece dinî önermelerin geçerliliği ortadan kalkar ve ilişki sona erer"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"zor","b":"Değerlendirme"},{"s":"Dinin gayesi için kitapta öne çıkarılan ifade hangisidir?","d":"Fert ve cemiyeti ıslah ederek dünya ve âhirette mutluluğa ulaştırmak","y":["Toplumu felsefî sorgulamaların etkisinden korumak ve ona kapalı tutmak","Doğa bilimlerinin yöntemini belirlemek ve araştırmacılara yön vermek","Siyasal iktidarın devamlılığını sağlamak ve onu meşrulaştırmak"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"orta","b":"Anlama"},{"s":"Din ile felsefenin ortak gayesi aşağıdakilerden hangisidir?","d":"Hakikati tanımak ve tanıtmak","y":["Deneysel veri toplamak ve arşivlemek","Siyasal güç kazanmak ve yönetmek","Sanat eserlerini dönemlere ayırmak"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"kolay","b":"Hatırlama"},{"s":"Hakikati açıklarken din ile felsefe arasındaki yargı farkı hangisidir?","d":"Din kesin yargılara, felsefe tartışmaya açık yargılara yer verir","y":["Din tartışmaya açık yargılara, felsefe kesin yargılara yer verir","İkisi de her konuda aynı kesinlikte yargı bildirir","İkisi de yargı bildirmekten kaçınıp soru sormakla yetinir"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"orta","b":"Analiz"},{"s":"Gazâlî, Fahreddin Râzî, İbn Rüşd, Anselmus ve Aquino’lu Thomas’ın ortak yönü hangisidir?","d":"Hem ilâhiyatçı hem filozof olarak anılmaları","y":["Mantıkçı pozitivist akıma bağlı olmaları","Din bilimlerinin kurucuları sayılmaları","Deneysel psikolojinin öncüleri olmaları"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Gayeler","z":"kolay","b":"Hatırlama"},{"s":"“Nereden geldik, nereye gidiyoruz, niçin yaratıldık?” soruları kimin ortak soruları arasında sayılır?","d":"Hem dinin hem felsefenin","y":["Deneysel fiziğin","Hukuk biliminin","Sanat tarihinin"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Sorular","z":"kolay","b":"Hatırlama"},{"s":"Ruh ile beden arasında nasıl bir ilişki bulunduğu sorusu din ile felsefenin hangi tür sorusuna örnektir?","d":"İkisinin de ele aldığı ortak metafizik sorulara","y":["Laboratuvar ortamında cevaplanan deneysel sorulara","Dil bilgisi kurallarını konu alan sorulara","Hukuk uygulamasına ilişkin pratik sorulara"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Sorular","z":"orta","b":"Uygulama"},{"s":"Din ve felsefenin sorularının hayatın dinamikliği sürdükçe yenilenmesi, bu iki alandan ne gerektirir?","d":"Dinamik kalmalarını; aksi hâlde hayata yön veremez ve problemleri çözemezler","y":["Eski cevapları değiştirmeden tekrarlamalarını ve yeni sorulara kapanmalarını","Birbirinden kopup ayrı dünyalara çekilmelerini ve ortak soru sormaktan vazgeçmelerini","Yeni soruları tartışma dışı bırakıp mevcut sorularla yetinmelerini"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Sorular","z":"orta","b":"Analiz"},{"s":"Din ve felsefe neden tek bir özel bilime indirgenemez?","d":"Varlığı bütünüyle kuşatan geniş ve üniversal tecrübeler oldukları için","y":["Bilgi üretmeyip salt inanca dayalı, bilimle ilgisi olmayan alanlar oldukları için","Eski çağlarda ortaya çıkıp sonraki dönemlerde bırakılmış alanlar oldukları için","Yöntemleri deney ve gözlemden oluşan, ölçülebilir alanlar oldukları için"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Realitelere yönelişleri","z":"orta","b":"Anlama"},{"s":"Yasa koyuculuk konusunda felsefe ile din arasındaki fark hangisidir?","d":"Felsefe yasaların kaynağını insan zihninde, din ise Allah’ın koyduğu kanunlarda görür","y":["Felsefe yasaların kaynağını Allah’ta, din ise insan zihninde görür ve bunu savunur","İkisi de varlıkta bir düzen bulunmadığını, yasa gibi görünenin tesadüf olduğunu ileri sürer","İkisi de yasayı koyanın devlet olduğunu, halkın ise onu uyguladığını kabul eder"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Realitelere yönelişleri","z":"zor","b":"Analiz"},{"s":"İmana giden epistemolojik süreçte basamaklar hangi sıradadır?","d":"İlgi, şüphe, zan, inanç, bilgi, iman","y":["İman, bilgi, inanç, zan, şüphe, ilgi","Zan, ilgi, bilgi, şüphe, iman, inanç","Bilgi, ilgi, iman, inanç, şüphe, zan"],"t":20,"p":"3. hafta: Zapoot (yeni, 20 soru)","k":"Realitelere yönelişleri","z":"zor","b":"Hatırlama"},{"s":"Bir öğrenci “din ile felsefe birbirine tamamen yabancıdır” diyor. Kitaptaki karşılaştırmaya göre en uygun cevap hangisidir?","d":"Konuları, kavramları, gayeleri ve soruları bakımından benzerlik gösterirler; ayrılıkları kaynakları, yöntemleri ve hükümlerin niteliğinde toplanır","y":["Aralarında adlandırma farkından başka fark yoktur; konuları, kaynakları ve yöntemleri bütünüyle aynıdır, bu yüzden ayrı iki alan sayılmaları yanlıştır ve terk edilmelidir","Konuları da gayeleri de ayrıdır; ortak görünen kavramlar tesadüfî benzerliklerden ibarettir ve bunlar arasında bağ kurmaya çalışmak yöntem bakımından yanlıştır","Ortak noktaları gayelerde toplanır; kavram, soru ve konu bakımından ise birbirinden kopuk iki ayrı alan oldukları açıktır ve karşılaştırma yapılamaz"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Kavramlar","z":"orta","b":"Değerlendirme"},{"s":"Bir filozof “Allah vardır ve birdir” hükmüne aklî delillerle ulaştığını söylüyor, başka bir filozof ise aynı delilleri yetersiz buluyor. Kitaptaki görüşe göre bu durum neyi gösterir?","d":"Filozofun yargısının ferdî ve tartışmaya açık olduğunu; dinî hükmün ise kesin kabul istediğini","y":["Aklî delillerin bir hükmü temellendirmeye elverişli olmadığını ve felsefenin bu yüzden değersiz kaldığını","Din ile felsefenin bu konuda birbirine zıt sonuçlara vardığını ve aralarında bağ kurulamayacağını","Delil gösterme çabasının dinî açıdan sakıncalı olduğunu ve felsefecinin bundan kaçınması gerektiğini"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Kavramlar","z":"zor","b":"Analiz"},{"s":"Bir yazar “Yunan filozofları vahiy geleneğinden bağımsız düşünmüştür” diyor. Kitapta bu iddiaya karşı hangi gerekçe öne sürülür?","d":"Ksenofanes’ten Plotinos’a pek çok filozof vahiy geleneğinden fikir ve kavram bakımından etkilenmiştir; Platon’a “Yunanca konuşan Musa” denmesi bunu gösterir","y":["Yunan filozofları vahyi bilinçli olarak reddedip onu yok saymaya çalışmıştır; bu yüzden bağımsızlıktan söz edilebilir ve bu bir delil sayılmalıdır","Vahiy ancak son dönemlerde yayılmıştır, Yunan filozofları ise ondan çok önce yaşamıştır; bu yüzden etkilenme düşünülemez ve tarihsel olarak imkânsızdır","Filozofların kavramları bütünüyle deneysel gözlemden türetilmiştir; bu yüzden vahyin kavram üretiminde bir rolü bulunmaz ve bulunamaz"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Kavramlar","z":"zor","b":"Değerlendirme"},{"s":"Tevhit dinlerinde Allah’ın varlığı ve birliği inananına ispat zorunluluğu getirmediği hâlde dinin düşünmeyi teşvik etmesi nasıl açıklanır?","d":"Körü körüne kabulü engellemek için yaratılmışlara bakıp düşünerek Yüce Varlık’ı anlamayı ve imanı makulleştirmeyi istemesiyle","y":["Düşünmenin imanı ortadan kaldıracağını ve bu yüzden zorunlu olarak sınırlanması gerektiğini göstermek istemesiyle","İnananı felsefe eğitimi almaya zorunlu tutan bir yükümlülük koymak ve bunu imanın şartı saymak istemesiyle","İmanın akıldan bütünüyle bağımsız bir alan olduğunu ve akıl yürütmenin ona zarar verdiğini belirtmek istemesiyle"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Kavramlar","z":"zor","b":"Analiz"},{"s":"Klasik felsefe ile modern felsefenin gayeleri karşılaştırıldığında hangi ayrım kitapta öne çıkarılır?","d":"Klasik felsefe varlığın hakikatini, modern felsefe güvenilir bilgiyi gaye edinir","y":["Klasik felsefe deneysel bilgiyi, modern felsefe ise metafiziği asıl gaye edinir ve ona yönelir","İkisi de aynı gayeyi taşır; aralarındaki tek ayrım yöntemde ve kullanılan dilde ortaya çıkar","Klasik felsefe belirli bir gayeden yoksundur, modern felsefe ise ahlâkı tek gaye olarak benimser"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Gayeler","z":"orta","b":"Analiz"},{"s":"Felsefenin görevinin kavram analizine indirgenmesi, kitaba göre hangi sonuca yol açar?","d":"Her felsefe sistemi kendi konusunu felsefenin biricik gayesi yapmak ister; bu, felsefenin genel tutumuyla bağdaşmaz","y":["Felsefe bütün problemleri kesin biçimde çözmüş olur ve bu durumda dinî açıklamalara ihtiyaç kalmaz ve tartışma sona erer","Felsefe ile din arasındaki bütün farklar ortadan kalkar ve iki alan tek bir alana dönüşmüş olur; ayrım anlamsızlaşır","Felsefenin metafizik ve ahlâkla ilişkisi güçlenir; bu alanlar felsefenin merkezine yerleşir ve daha da genişler"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Gayeler","z":"zor","b":"Analiz"},{"s":"Batı felsefesinde bilime dayalı anlayış yaygınlaşınca sistemlerin birbirini yıkan bir yapıya dönüştüğü söyleniyor. Kitaptaki gerekçe nedir?","d":"Hakikatler madde dünyasında arandığından, bu dünyaya dair bilgiler değiştikçe hakikatler de değişmiştir","y":["Filozofların birbirleriyle konuşmaması ve görüş alışverişi yapmaması sistemlerin dağılmasına yol açmıştır","Felsefenin dinden etkilenmesi sistemlerin tutarsızlaşmasına ve birbirini yıkmasına neden olmuştur","Bilimin felsefeyi etkilememesi sistemlerin gelişim çizgisini koparmış ve çatışmaya sürüklemiştir"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Gayeler","z":"zor","b":"Değerlendirme"},{"s":"Din ve felsefenin ortak amaçlar taşıması iki alanın ilişkisi bakımından hangi sonuca götürür?","d":"Hakikati tanımayı ve insana hizmeti hedefledikleri için çoğu noktada yaklaşırlar; kaynak ve yargı niteliği bakımından ise ayrışırlar","y":["Aynı yöntemi kullandıkları için birbirinin yerine geçebilirler; bu durumda biri diğerini gereksiz kılar ve ortadan kaldırır","Aralarında fark kalmadığı için ayrı iki alan olarak anılmaları yanlıştır; tek bir alan sayılmalı ve adlandırma buna göre yapılmalıdır","Ortak amaç taşıdıkları için birbirinden bağımsız ilerlerler; birbirini etkileme imkânı bulunmaz ve karşılaşmaları beklenmez"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Gayeler","z":"orta","b":"Değerlendirme"},{"s":"Din ve felsefenin soruları ortak olsa da cevaplarının niteliği farklılaşabilir. Aşağıdakilerden hangisi bu farkı en iyi örnekler?","d":"Âlemin yaratılışı sorusuna din vahye dayanarak kesin cevap verirken felsefe akıl yürütmelerle birbirinden ayrışan cevaplar önerir","y":["Her iki alan da âlemin yaratılışı sorusunu sormaz; bu soruyu başka bilimlerin alanına bırakır ve ona cevap aramaz","İki alan da bu soruya laboratuvar deneyleriyle cevap arar ve elde ettikleri sonuçları birbiriyle karşılaştırır","Din soruyu gereksiz bularak reddeder, felsefe ise cevap vermeyi zorunlu bulur ve kesin hüküm bildirir"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Sorular","z":"zor","b":"Uygulama"},{"s":"Felsefî inanış ile dinî iman arasındaki fark kitapta nasıl açıklanır?","d":"Felsefî inanış tahlil, tenkit ve şüpheden geçen bir kabullenmedir; dinî iman ise vahiyle bildirilen hükme kesin tasdiktir","y":["Felsefî inanış kesin tasdiktir ve şüphe taşımaz; dinî iman ise ihtimale ve kanaate dayalı, kesinlik taşımayan bir kabullenmedir","İkisi de aynı basamakta durur ve aynı kesinliği taşır; aralarındaki fark adlandırma düzeyinde kalır ve içerik bakımından fark yoktur","Felsefî inanış duygudan, dinî iman ise salt akıl yürütmeden doğar; bu yüzden ikisi birbirinden ayrılır ve zıt kutuplar oluşturur"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Realitelere yönelişleri","z":"zor","b":"Analiz"},{"s":"Bir öğrenci “iman bir tür bilgidir, o hâlde bilgi ile iman aynı şeydir” diyor. İman sürecindeki basamaklara göre bu çıkarım için ne söylenebilir?","d":"Yanlıştır; iman bilgi ve inanç basamaklarına dayanır, imanda bilgi vardır fakat iman bilgiden ibaret değildir","y":["Doğrudur; çünkü iman ile bilgi arasında basamak bulunmaz ve ikisi aynı düzeydedir","Doğrudur; çünkü iman en alt basamaktır ve bilgi de aynı alt düzeyde yer alır","Yanlıştır; çünkü imanın içinde bilgiye ait bir unsur bulunmaz, ikisi bağımsız ayrı alanlardır ve karıştırılmamalıdır"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Realitelere yönelişleri","z":"zor","b":"Değerlendirme"},{"s":"Dinî imanın kalpte tasdik ve dille ikrar olarak tarifinde hangi unsurların bir arada bulunduğu vurgulanır?","d":"Duygu, şuur, irade ve akla dayanan bir tasdik, güven ve kesinlik","y":["Davranış biçimine indirgenen bir uyum ve görünüşe dönük bir tavır","Toplumsal aidiyeti ve topluluğa katılımı esas alan bir bağlılık","Sözlü ikrarın tek başına yeterli sayıldığı bir beyan ve tekrar"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Realitelere yönelişleri","z":"orta","b":"Anlama"},{"s":"Dogmatik felsefelerin bir “felsefî iman” taşıdığı yönündeki eleştiri neye dayanır?","d":"Bu sistemlerin, doğruluğunu göstermeye çalıştıkları ilke ve inanç esaslarından yola çıkmasına","y":["Bu sistemlerin dayandıkları ilkeleri kanıtlayıp sorgulayarak ilerlemesine ve kabul taşımamasına","Bu sistemlerin deney ve gözlemle ispatlanmış sonuçlardan oluşmasına ve doğrulanmış olmasına","Bu sistemlerin dinî metinlerden birebir aktarılmasına ve dinin yorumu sayılmasına"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Realitelere yönelişleri","z":"zor","b":"Analiz"},{"s":"Fichte’ye göre hakikat tektir. Kitaba göre gerçek bir felsefenin şartı bununla nasıl ilişkilendirilir?","d":"İnsanın mutlak bir hakikatin bulunduğunu ve ona araştırarak ulaşılabileceğini kabul etmesi gerekir","y":["İnsanın hakikat diye bir şeyin bulunmadığını baştan varsayması ve araştırmayı bu zemin üzerinde yürütmesi gerekir","Hakikatin ancak duyularla kavranabileceğini kabul etmesi ve başka bilgi yollarını dışarıda bırakması gerekir","Hakikat arayışının felsefeyle değil deneysel bilimle sürdürüleceğini kabul etmesi ve felsefeden vazgeçmesi gerekir"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Gayeler","z":"zor","b":"Analiz"},{"s":"Aşağıdaki eşleştirmelerden hangisi kitaptaki karşılaştırmaya göre doğrudur?","d":"Gayeleri bakımından benzerlik; kaynakları ve metotları bakımından farklılık","y":["Kaynakları bakımından benzerlik; gayeleri bakımından farklılık","Sorularının tamamı bakımından farklılık; yöntemleri bakımından benzerlik","Konuları bakımından farklılık; kavramları bakımından farklılık"],"t":60,"p":"3. hafta: Quiz (yeni, 15 soru)","k":"Kavramlar","z":"orta","b":"Uygulama"}]$j$::jsonb) x
  where not exists (select 1 from public.questions q where q.subject_id = v_icerik and lower(q.soru) = lower(x->>'s'));
end $$;
